const {source}= $('Input').first().json;const raw=$input.first().json;let env,data,note;
try{if(raw.error)throw Error('Request failed');const body=String(raw.response||raw.data||'');const frames=body.split('\n').filter(s=>s.startsWith('data:')).map(s=>s.slice(5).trim());env=JSON.parse(frames.length?frames[frames.length-1]:body);if(env.error||env.result?.isError)throw Error('MCP tool error');const t=(env.result?.content||[]).filter(c=>c.type==='text').map(c=>c.text).join('\n');if(/^No recent news found/i.test(t)){data={news:[]};}else{data=JSON.parse(t.replace(/:\s*(NaN|-?Infinity)(\s*[,}\]])/g,': null$2'));if(!Array.isArray(data.news))throw Error('Unexpected news schema');}}catch(e){note=e.message;data={news:[]};}
const events=data.news.filter(n=>n.title&&/^https?:\/\//.test(n.url)).map(n=>({source_id:source.id,source_name:n.provider||'Yahoo Finance',source_category:'company',source_item_id:n.url,title:String(n.title).slice(0,500),url:n.url,snippet:String(n.summary||'').slice(0,3000),published_on:n.pubDate||null,collected_at:new Date().toISOString(),evidence_scope:'headline_and_feed_summary'}));
return [{json:{events,status:{id:source.id,ok:!note,count:events.length,error:note||null,possibly_truncated:(data.news||[]).length>=20,coverage:'Ticker feed may contain unrelated stories; matching required'}}}];
